88: #if defined(__APPLE__)
89:     struct mach_task_basic_info info;
90:     mach_msg_type_number_t infoCount = MACH_TASK_BASIC_INFO_COUNT;
91:     if (task_info(mach_task_self(), MACH_TASK_BASIC_INFO, reinterpret_cast<task_info_t>(&info), &infoCount) != KERN_SUCCESS)
92:         return static_cast<size_t>(0);
93:     return static_cast<size_t>(info.resident_size);
94: #else
95:     long rss  = 0;
96:     FILE * fp = nullptr;
97:     if ((fp = fopen("/proc/self/statm", "r")) == nullptr)
98:         return static_cast<size_t>(0L);
99:     if (fscanf(fp, "%*s%ld", &rss ) != 1) {
100:         fclose(fp);
101:         return static_cast<size_t>(0);
102:     }
103:     fclose(fp);
104:     return static_cast<size_t>(rss) * static_cast<size_t>(sysconf(_SC_PAGESIZE));
