145: void check_memory(char const * component_name) {
146:     if (g_max_memory == 0) return;
147:     g_counter++;
148:     if (g_counter >= LEAN_CHECK_MEM_THRESHOLD) {
149:         g_counter = 0;
150:         // We try first get_peak_rss because it is much faster
151:         // than get_current_rss on Linux.
152:         size_t r = get_peak_rss();
153:         if (r > 0 && r < g_max_memory) return;
154:         r = get_current_rss();
155:         if (r == 0 || r < g_max_memory) return;
156:         throw_memory_exception(component_name);
